import java.util.ArrayDeque;
import java.util.Queue;
import java.util.List;
import java.util.ArrayList;

class Solution {
    public void solve(char[][] board) {
        int rows = board.length;
        int cols = board[0].length;
        int[] rowStep = {-1, 1, 0, 0};
        int[] colStep = {0, 0, -1, 1};
        for (int startRow = 0; startRow < rows; startRow++) {
            for (int startCol = 0; startCol < cols; startCol++) {
                if (board[startRow][startCol] != 'O') continue;
                boolean[][] seen = new boolean[rows][cols];
                Queue<int[]> queue = new ArrayDeque<>();
                List<int[]> component = new ArrayList<>();
                queue.offer(new int[] {startRow, startCol});
                seen[startRow][startCol] = true;
                boolean touchesEdge = false;
                while (!queue.isEmpty()) {
                    int[] cell = queue.poll();
                    component.add(cell);
                    if (cell[0] == 0 || cell[0] == rows - 1 || cell[1] == 0 || cell[1] == cols - 1) touchesEdge = true;
                    for (int direction = 0; direction < 4; direction++) {
                        int nextRow = cell[0] + rowStep[direction];
                        int nextCol = cell[1] + colStep[direction];
                        if (nextRow >= 0 && nextRow < rows && nextCol >= 0 && nextCol < cols
                                && board[nextRow][nextCol] == 'O' && !seen[nextRow][nextCol]) {
                            seen[nextRow][nextCol] = true;
                            queue.offer(new int[] {nextRow, nextCol});
                        }
                    }
                }
                if (!touchesEdge) for (int[] cell : component) board[cell[0]][cell[1]] = 'X';
            }
        }
    }
}

