import java.util.ArrayDeque;
import java.util.Queue;

class Solution {
    public void solve(char[][] board) {
        int rows = board.length;
        int cols = board[0].length;
        int[] rowStep = {-1, 1, 0, 0};
        int[] colStep = {0, 0, -1, 1};
        Queue<int[]> queue = new ArrayDeque<>();
        for (int row = 0; row < rows; row++) {
            addIfOpen(board, row, 0, queue);
            addIfOpen(board, row, cols - 1, queue);
        }
        for (int col = 0; col < cols; col++) {
            addIfOpen(board, 0, col, queue);
            addIfOpen(board, rows - 1, col, queue);
        }
        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            for (int direction = 0; direction < 4; direction++) {
                int nextRow = cell[0] + rowStep[direction];
                int nextCol = cell[1] + colStep[direction];
                if (nextRow >= 0 && nextRow < rows && nextCol >= 0 && nextCol < cols) {
                    addIfOpen(board, nextRow, nextCol, queue);
                }
            }
        }
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (board[row][col] == 'O') board[row][col] = 'X';
                else if (board[row][col] == '#') board[row][col] = 'O';
            }
        }
    }

    private void addIfOpen(char[][] board, int row, int col, Queue<int[]> queue) {
        if (board[row][col] == 'O') {
            board[row][col] = '#';
            queue.offer(new int[] {row, col});
        }
    }
}
